        <!-- Content -->
        <div class="mt-2 rounded-[25px] bg-T-200 p-6 lg:mt-0">
          <UiTypography as="p" size="mdLg" weight="regular" color="emphasis" class="leading-[30px]">
            {{ aboutPage.hero }}
          </UiTypography>
          <UiTypography as="p" size="mdLg" weight="regular" color="emphasis" class="mt-4 leading-[30px]">
            {{ aboutPage.heroExtra }}
          </UiTypography>
        </div>
      </section>

      <!-- Article -->
      <section class="mt-10 w-full max-w-[1020px] rounded-[16px] bg-T-50 lg:mt-12 lg:p-8 lg:shadow-[0_8px_30px_rgba(0,0,0,0.06)]">
        <template v-for="(section, si) in aboutPage.sections" :key="si">
          <UiTypography
            as="h2"
            size="xl"
            weight="bold"
            color="default"
            class="leading-[28px]"
            :class="si > 0 ? 'mt-8' : ''"
          >
            {{ section.heading }}
          </UiTypography>
          <UiTypography
            v-for="(para, pi) in section.paragraphs"
            :key="`p-${pi}`"
            as="p"
            size="mdLg"
            weight="regular"
            color="emphasis"
            class="mt-4 leading-[30px]"
          >
            {{ para }}
          </UiTypography>
        </template>
      </section>

      <!-- CEO / store description band (same as the landing page) -->
      <LandingCeoSection class="mt-10 w-full lg:mt-12" />
    </main>

    <LandingSiteFooter class="mt-auto" />
    <LandingMobileBottomNav />
  </div>
</template>